package com.iare.club.service;
import com.google.zxing.*;import com.google.zxing.client.j2se.MatrixToImageWriter;import com.google.zxing.common.BitMatrix;import com.google.zxing.qrcode.QRCodeWriter;
import com.iare.club.entity.*;import com.iare.club.repository.*;import java.io.*;import java.math.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;
@Service public class UpiPaymentService{
 private final UpiPaymentRequestRepository requests;private final MerchantPaymentConfigRepository configs;private final DepositService deposits;private final AdminAuditLogRepository audits;private final MerchantPaymentConfigHistoryRepository history;private final YoupiGatewayClient youpi;private final Clock clock;private final String upiId;private final boolean authorizedAutoCredit;
 public UpiPaymentService(UpiPaymentRequestRepository r,MerchantPaymentConfigRepository c,DepositService d,AdminAuditLogRepository a,MerchantPaymentConfigHistoryRepository history,YoupiGatewayClient youpi,Clock clock,@Value("${payments.upi.id:}")String upiId,@Value("${payments.verification.authorized-provider.auto-credit-enabled:false}")boolean auto){requests=r;configs=c;deposits=d;audits=a;this.history=history;this.youpi=youpi;this.clock=clock;this.upiId=upiId==null?"":upiId.strip();authorizedAutoCredit=auto;}
 @Transactional public UpiPaymentRequest create(AppUser user,BigDecimal amount){if(!isCheckoutEnabled())throw new DepositService.FinancialException("UPI payments are unavailable because UPI_ID is not configured");Deposit deposit=deposits.createUpi(user,amount);Instant now=clock.instant();UpiPaymentRequest payment=new UpiPaymentRequest(user,deposit,deposit.getPaymentReference(),deposit.getAmount(),upiId,"Fundraiser",now,now.plus(Duration.ofMinutes(15)));payment.markPending(now);return requests.save(payment);}
 @Transactional(readOnly=true)public MerchantPaymentConfig activeConfig(){return configs.findBySingletonKey("PRIMARY").filter(MerchantPaymentConfig::isActive).orElseThrow(()->new DepositService.FinancialException("Merchant UPI configuration is not active"));}
 @Transactional(readOnly=true)public Optional<MerchantPaymentConfig> config(){return configs.findBySingletonKey("PRIMARY");}
 @Transactional public MerchantPaymentConfig saveConfig(String name,String upi,String bank,String lastFour,boolean active,String admin){if(name==null||name.isBlank()||upi==null||!upi.matches("^[A-Za-z0-9._-]{2,256}@[A-Za-z0-9._-]{2,64}$"))throw new DepositService.FinancialException("Enter a valid merchant name and UPI ID");String safeBank=bank==null||bank.isBlank()?"Not specified":bank.strip();String last=lastFour==null?null:lastFour.strip();if(last!=null&&!last.isEmpty()&&!last.matches("\\d{4}"))throw new DepositService.FinancialException("Store only the last four account digits");MerchantPaymentConfig c=configs.findBySingletonKey("PRIMARY").orElseGet(()->new MerchantPaymentConfig(name.strip(),upi.strip(),safeBank,last,active,admin,clock.instant()));c.update(name.strip(),upi.strip(),safeBank,last,active,admin,clock.instant());c=configs.saveAndFlush(c);youpi.updateUpiSettings(c);history.save(new MerchantPaymentConfigHistory(c,admin,clock.instant()));return c;}
 @Transactional(readOnly=true)public UpiPaymentRequest forUser(String reference,AppUser user){UpiPaymentRequest p=requests.findByReference(reference).orElseThrow(()->new DepositService.FinancialException("Payment not found"));if(!p.getUser().getId().equals(user.getId()))throw new DepositService.FinancialException("Payment not found");return p;}
 public String uri(UpiPaymentRequest p){return "upi://pay?pa="+enc(p.getMerchantUpiId())+"&pn="+enc("Fundraiser")+"&am="+p.getAmount().setScale(2).toPlainString()+"&cu=INR&tr="+enc(p.getReference())+"&tn="+enc("Fundraiser deposit "+p.getReference());}
 public byte[] qr(UpiPaymentRequest p){try{BitMatrix matrix=new QRCodeWriter().encode(uri(p),BarcodeFormat.QR_CODE,360,360);ByteArrayOutputStream out=new ByteArrayOutputStream();MatrixToImageWriter.writeToStream(matrix,"PNG",out);return out.toByteArray();}catch(Exception e){throw new IllegalStateException("Could not generate payment QR",e);}}
 @Transactional public UpiPaymentRequest observeYoupi(String reference,String transaction,String utr,String event,String settlement){UpiPaymentRequest p=requests.findByReferenceForUpdate(reference).orElseThrow(()->new DepositService.FinancialException("Payment not found"));Instant now=clock.instant();if("RECONCILED".equalsIgnoreCase(event)||"RECONCILED".equalsIgnoreCase(settlement))p.requireReview("YOUPI",transaction,utr,"YouPI operator reconciliation is not independent bank confirmation",now);else p.observed("YOUPI",transaction,utr,"Experimental alert observation: "+event,now);return requests.save(p);}
 @Transactional public UpiPaymentRequest applyYoupiOutcome(String reference,String transaction,String utr,String event,String settlement){UpiPaymentRequest p=requests.findByReferenceForUpdate(reference).orElseThrow(()->new DepositService.FinancialException("Payment not found"));Instant now=clock.instant();if("OBSERVED_SUCCESS".equalsIgnoreCase(event))p.observed("YOUPI",transaction,utr,"YouPI observer signal; not reconciled",now);else if("RECONCILED".equalsIgnoreCase(event)&&"RECONCILED".equalsIgnoreCase(settlement))p.requireReview("YOUPI",transaction,utr,"YouPI statement reconciliation requires authorized review before wallet credit",now);else if("MANUAL_REVIEW".equalsIgnoreCase(event))p.requireReview("YOUPI",transaction,utr,"YouPI could not unambiguously match the observation",now);else if("FAILED".equalsIgnoreCase(event)||"EXPIRED".equalsIgnoreCase(event)||"CANCELLED".equalsIgnoreCase(event))p.gatewayFailed(event,"YouPI checkout outcome",now);else throw new DepositService.FinancialException("Unsupported YouPI event");return requests.save(p);}
 @Transactional public UpiPaymentRequest authorizedVerify(String reference,BigDecimal amount,String transaction,String utr,String merchantUpi){if(!authorizedAutoCredit)throw new DepositService.FinancialException("Authorized-provider automatic credit is disabled");UpiPaymentRequest p=requests.findByReferenceForUpdate(reference).orElseThrow(()->new DepositService.FinancialException("Payment not found"));if(amount==null||amount.compareTo(p.getAmount())!=0)throw new DepositService.FinancialException("Payment amount mismatch");if(merchantUpi==null||!merchantUpi.equalsIgnoreCase(p.getMerchantUpiId()))throw new DepositService.FinancialException("Merchant destination mismatch");Instant now=clock.instant();p.verified("AUTHORIZED_PROVIDER",transaction,utr,"Authenticated provider confirmation",now);deposits.creditVerifiedUpi(reference,transaction,utr);p.credited(now);return requests.save(p);}
 @Transactional public UpiPaymentRequest manualVerify(long id,String transaction,String utr,String evidence,String admin){UpiPaymentRequest p=requests.findById(id).orElseThrow();String before=p.getStatus().name();if(evidence==null||evidence.strip().length()<10||utr==null||utr.isBlank())throw new DepositService.FinancialException("Bank-record evidence and UTR are required");Instant now=clock.instant();p.verified("ADMIN_BANK_REVIEW",transaction,utr,evidence,now);deposits.creditVerifiedUpi(p.getReference(),transaction,utr);p.credited(now);requests.save(p);audits.save(new AdminAuditLog(admin,"UPI_PAYMENT",p.getId(),"BANK_RECORD_VERIFIED",before,p.getStatus().name(),evidence,now));return p;}
 @Transactional(readOnly=true)public java.util.List<MerchantPaymentConfigHistory> configHistory(){return history.findTop50ByOrderByChangedAtDesc();}public YoupiGatewayClient.ServiceStatus gatewayStatus(){return youpi.status();}public boolean isYoupiIntegrated(){return youpi.isEnabled();}public boolean isCheckoutEnabled(){return upiId.matches("^[A-Za-z0-9._-]{2,256}@[A-Za-z0-9._-]{2,64}$");}public boolean isAuthorizedAutoCredit(){return authorizedAutoCredit;}private static String enc(String s){return URLEncoder.encode(s,StandardCharsets.UTF_8).replace("+","%20");}
}
